// Assign a single run_id shared by every item in this execution
const runId = $execution.id + '_' + Date.now();
const item = items[0];
item.json.run_id = runId;
item.json.run_started_at = new Date().toISOString();
return [item];

return items.map((item, i) => {
  item.json.issue_id = `$execution.id || 'run'}_${item.json.file_path}_${item.json.rule}_${i}`.replace(/[^a-zA-Z0-9_\-]/g,'_');
  // baseline maintainability metric extracted from the SonarQube message when possible
  const m = /from (\d+) to the (\d+) allowed/i.exec(item.json.message || '');
  item.json.baseline_metric_value = m ? parseInt(m[1], 10) : null;
  item.json.target_metric_value = m ? parseInt(m[2], 10) : null;
  return item;
});

// Deterministic grouping: one output item per unique file_path,
// carrying the full list of issues reported for that file.
const groups = {};
for (const item of items) {
  const fp = item.json.file_path;
  if (!groups[fp]) {
    groups[fp] = { file_path: fp, run_id: $execution.id, issues: [] };
  }
  groups[fp].issues.push({
    issue_id: item.json.issue_id,
    rule: item.json.rule,
    severity: item.json.severity,
    type: item.json.type,
    message: item.json.message,
    line: item.json.line,
    textRange: item.json.textRange,
    baseline_metric_value: item.json.baseline_metric_value,
    target_metric_value: item.json.target_metric_value
  });
}
return Object.values(groups).map(g => ({ json: { ...g, retry_count: 0, status: 'PENDING', feedback_prompt: '' } }));

const code = $json.Source_code;
const lines = code.split(/\r?\n/);
return [{ json: { total_lines: lines.length, lines: lines.map((line, i) => ({ line_number: i + 1, code: line })) } }];

// Sequential join (no position-based merge needed): file metadata came from
// the current 'Loop Over Files' batch item, parsed source came from this branch.
const fileMeta = $('Loop Over Files').item.json;
const parsed = $json;
return [{ json: {
  file_path: fileMeta.file_path,
  run_id: fileMeta.run_id,
  issues: fileMeta.issues,
  retry_count: fileMeta.retry_count || 0,
  feedback_prompt: fileMeta.feedback_prompt || '',
  total_lines: parsed.total_lines,
  lines: parsed.lines,
  source_code: parsed.lines.map(l => l.code).join('\n')
} }];

const fileContext = $('Prepare File Context').first().json;
const allLines = fileContext.lines ?? [];

return $input.all().map(item => {
  const issue = item.json;

  const start =
    issue.textRange?.startLine ??
    issue.line ??
    1;

  const end =
    issue.textRange?.endLine ??
    start;

  const snippet = allLines.filter(line =>
    line.line_number >= start - 10 &&
    line.line_number <= end + 10
  );

  return {
    json: {
      ...issue,
      context_code: snippet
        .map(line => `${line.line_number}: ${line.code}`)
        .join('\n')
    }
  };
});

const ragItems = $input.all();
const analyzerItems = $('Analyzer Agent').all();
const contextItems = $('Build Context Window').all();

const results = [];

for (let i = 0; i < ragItems.length; i++) {
  const ragItem = ragItems[i];
  const analyzerItem = analyzerItems[i];
  const contextItem = contextItems[i];

  let analyzerOut = {};
  let ragOut = {};

  // Parse Analyzer output
  try {
    analyzerOut = JSON.parse(
      analyzerItem?.json?.output ?? '{}'
    );
  } catch (e) {
    analyzerOut = {
      parse_error: String(e),
      raw_output: analyzerItem?.json?.output ?? ''
    };
  }

  // Parse RAG output
  try {
    ragOut = JSON.parse(
      ragItem?.json?.output ?? '{}'
    );
  } catch (e) {
    ragOut = {
      parse_error: String(e),
      raw_output: ragItem?.json?.output ?? ''
    };
  }

  results.push({
    json: {
      issue_id:
        analyzerOut.issue_id ??
        ragOut.issue_id ??
        contextItem?.json?.issue_id ??
        null,

      file_path:
        analyzerOut.file_path ??
        ragOut.file_path ??
        contextItem?.json?.file_path ??
        null,

      analysis: analyzerOut,

      knowledge: ragOut
    }
  });
}

return results;

const fileCtx = $('Prepare File Context').item.json;
const issuesAnalysis = $json.issues_analysis || [];
return [{ json: {
  file_path: fileCtx.file_path,
  run_id: fileCtx.run_id,
  source_code: fileCtx.source_code,
  issues: fileCtx.issues,
  issues_analysis: issuesAnalysis,
  retry_count: fileCtx.retry_count || 0,
  feedback_prompt: fileCtx.feedback_prompt || ''
} }];

const raw = $input.first().json.output ?? '';

if (!raw) {
  throw new Error('Output dari Refactor Agent kosong.');
}

let data = raw;

for (let i = 0; i < 3; i++) {
  if (typeof data !== 'string') break;
  let text = data.trim();
  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  try {
    data = JSON.parse(text);
  } catch (e) {
    break;
  }
}

let modifiedCode = '';

if (data && typeof data === 'object' && typeof data.modified_code === 'string') {
  modifiedCode = data.modified_code;
}

if (!modifiedCode) {
  const text = typeof data === 'string' ? data : raw;
  const markerRegex = /["\\]*modified_code["\\]*\s*:\s*"/;
  const match = markerRegex.exec(text);

  if (match) {
    const start = match.index + match[0].length;
    let escaped = '';
    let escapedChar = false;

    for (let i = start; i < text.length; i++) {
      const char = text[i];
      if (escapedChar) {
        escaped += '\\' + char;
        escapedChar = false;
        continue;
      }
      if (char === '\\') {
        escapedChar = true;
        continue;
      }
      if (char === '"') break;
      escaped += char;
    }

    try {
      modifiedCode = JSON.parse(`"${escaped}"`);
    } catch (e) {
      modifiedCode = escaped
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '\r')
        .replace(/\\t/g, '\t')
        .replace(/\\"/g, '"')
        .replace(/\\\\/g, '\\');
    }
  }
}

if (!modifiedCode) {
  throw new Error('modified_code tidak ditemukan pada output Refactor Agent.');
}

// FIX: kembalikan seluruh konteks (...ctx) DAN bungkus hasil sebagai refactor.modified_code
// supaya kompatibel dengan semua node downstream (AST/Signature Diff, Validation Agent,
// Mark Success, Build Retry Feedback, Prepare Original File Binary, dst.)
const ctx = $('Rebuild Full File Context').item.json;

return [{
  json: {
    ...ctx,
    refactor: { modified_code: modifiedCode }
  }
}];

const ctx = $('Parse Refactor Output').item.json;
const out = $json.stdout || '';
const failed = /EXITCODE:(?!0)\d/.test(out) || /error/i.test(out);
return [{ json: { ...ctx, syntax_ok: !failed, syntax_output: out } }];

// Deterministic structural check. Replace with ts-morph / @typescript-eslint/parser
// for a real AST diff. This heuristic version checks exported symbols and duplicate
// function declarations as a first line of defense.
const ctx = $json;
const original = ctx.source_code || '';
const candidate = (ctx.refactor && ctx.refactor.modified_code) || '';
const exportRegex = /export\s+(default\s+)?function\s+([A-Za-z0-9_]+)/g;
const origExports = new Set([...original.matchAll(exportRegex)].map(m => m[2] || 'default'));
const newExports = new Set([...candidate.matchAll(exportRegex)].map(m => m[2] || 'default'));
const removed = [...origExports].filter(x => !newExports.has(x));
const funcNameRegex = /function\s+([A-Za-z0-9_]+)\s*\(/g;
const names = [...candidate.matchAll(funcNameRegex)].map(m => m[1]);
const duplicates = names.filter((n, i) => names.indexOf(n) !== i);
const structurallyOk = removed.length === 0 && duplicates.length === 0 && candidate.trim().length > 0;
return [{ json: { ...ctx, structural_ok: structurallyOk, removed_exports: removed, duplicate_functions: [...new Set(duplicates)] } }];

