const ctx = $('AST/Signature Diff').item.json;
let judged = {};

try {
  let output = $json.output;

  // Hapus markdown code block jika ada
  if (output.includes('```json')) {
    output = output.replace(/```json\s*/g, '').replace(/```\s*$/g, '');
  } else if (output.includes('```')) {
    output = output.replace(/```\s*/g, '').replace(/```\s*$/g, '');
  }

  judged = JSON.parse(output);
} catch(e) {
  judged = { functionally_equivalent: false, reasoning: 'parse_error: ' + e.message };
}

const functionalOk = ctx.structural_ok && judged.functionally_equivalent === true;
return [{ json: { ...ctx, functional_ok: functionalOk, validation_agent_result: judged } }];

const ctx = $json;
const reasons = [];
if (ctx.syntax_ok === false) reasons.push('SYNTAX ERROR:\n' + (ctx.syntax_output || ''));
if (ctx.structural_ok === false) reasons.push('STRUCTURAL DIFF FAILED: removed exports=' + JSON.stringify(ctx.removed_exports) + ', duplicate functions=' + JSON.stringify(ctx.duplicate_functions));
if (ctx.functional_ok === false && ctx.validation_agent_result) reasons.push('FUNCTIONAL EQUIVALENCE FAILED: ' + ctx.validation_agent_result.reasoning + ' Risks: ' + JSON.stringify(ctx.validation_agent_result.flagged_risks || []));
if (ctx.maintainability_target_met === false) reasons.push(`MAINTAINABILITY TARGET NOT MET: complexity is ${ctx.new_metric_value}, target is <= ${ctx.target_metric_value}.`);
const retryCount = (ctx.retry_count || 0) + 1;
return [{ json: {
  file_path: ctx.file_path, run_id: ctx.run_id, source_code: ctx.source_code, issues: ctx.issues,
  issues_analysis: ctx.issues_analysis, retry_count: retryCount,
  feedback_prompt: reasons.join('\n---\n'),
  last_candidate_code: (ctx.refactor && ctx.refactor.modified_code) || ''
} }];

return [{ json: {
  run_id: $json.run_id, file_path: $json.file_path, status: $json.status,
  retry_attempts: $json.retry_count || 0,
  baseline_metric_value: $json.baseline_metric_value, new_metric_value: $json.new_metric_value,
  target_metric_value: $json.target_metric_value, complexity_reduction_pct: $json.complexity_reduction_pct,
  applied_patterns: ($json.refactor && $json.refactor.applied_patterns) || [],
  warnings: ($json.refactor && $json.refactor.warnings) || [],
  logged_at: new Date().toISOString()
} }];

const records = $json.file_records || [];
const total = records.length;
const success = records.filter(r => r.status === 'SUCCESS').length;
const maxRetryExceeded = records.filter(r => r.status === 'MAX_RETRY_EXCEEDED').length;
const avgReduction = total ? records.reduce((s, r) => s + (r.complexity_reduction_pct || 0), 0) / total : 0;
const avgRetries = total ? records.reduce((s, r) => s + (r.retry_attempts || 0), 0) / total : 0;
return [{ json: {
  total_files: total, success_count: success, max_retry_exceeded_count: maxRetryExceeded,
  success_rate_pct: total ? Math.round((success / total) * 100) : 0,
  avg_complexity_reduction_pct: Math.round(avgReduction), avg_retry_attempts: Math.round(avgRetries * 100) / 100,
  generated_at: new Date().toISOString(), records
} }];

const m = $json;
const header = 'file_path,status,retry_attempts,baseline_metric_value,new_metric_value,target_metric_value,complexity_reduction_pct\n';
const rows = m.records.map(r => [r.file_path, r.status, r.retry_attempts, r.baseline_metric_value, r.new_metric_value, r.target_metric_value, r.complexity_reduction_pct].join(',')).join('\n');
const csv = header + rows;
return [{ json: { ...m }, binary: { data: { data: Buffer.from(csv).toString('base64'), mimeType: 'text/csv', fileName: 'evaluation_dataset.csv' } } }];

const m = $('Compute Framework Metrics').item.json;
const narrative = $json.output || '';
const html = `<html><body><h1>Maintainability Framework Evaluation Report</h1>
<p>Generated: ${m.generated_at}</p>
<ul><li>Total files processed: ${m.total_files}</li><li>Successful (target met): ${m.success_count}</li><li>Max retry exceeded: ${m.max_retry_exceeded_count}</li><li>Success rate: ${m.success_rate_pct}%</li><li>Average complexity reduction: ${m.avg_complexity_reduction_pct}%</li><li>Average retry attempts: ${m.avg_retry_attempts}</li></ul>
<h2>Narrative Summary</h2><p>${narrative.replace(/
/g, '<br/>')}</p>
<h2>Per-file Records</h2><pre>${JSON.stringify(m.records, null, 2)}</pre>
</body></html>`;
return [{ json: { generated_at: m.generated_at }, binary: { data: { data: Buffer.from(html).toString('base64'), mimeType: 'text/html', fileName: 'evaluation_report.html' } } }];

const code = $json.refactor.modified_code;   // bukan lagi $json.modified_code

const parts = ($json.file_path || '').split('.');
const ext = parts.length > 1 ? parts.pop() : 'txt';

return [{
  json: $json,
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(code, "utf8"),
      `candidate.${ext}`
    )
  }
}];

// Sebelum "Backup Original File" — convert source_code asli ke binary
return [{
  json: $json,
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from($json.source_code, "utf8"), $json.file_path.split('/').pop()) }
}];

// Sebelum "Write Final Refactored File" — convert final_code ke binary
const ext = $json.file_path.split('.').pop();
return [{
  json: $json,
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from($json.final_code, "utf8"), $json.file_path.split('/').pop()) }
}];

